Chapter.Code:
class ISpatialIndex
{
public:
    virtual QueryAABB(...)=0;
    virtual QuerySphere(...)=0;
    virtual Raycast(...)=0;
    virtual Nearest(...)=0;
    virtual FindPath(...)=0;
};

struct AABBQuery;
struct SphereQuery;
struct RayQuery;
struct PointQuery;
struct NearestQuery;

enum class SpatialCapability : std::uint32_t
{
    AABB    = 1u << 0,
    Sphere  = 1u << 1,
    Ray     = 1u << 2,
    Point   = 1u << 3,
    Nearest = 1u << 4,
    Path    = 1u << 5
};

template<class T>
concept AABBQueryable =
    requires(
        const T& index,
        const SpatialAABB& bounds,
        SpatialLayerMask mask)
{
    {
        index.QueryAABB(bounds, mask)
    } -> std::same_as<SpatialOverlapResult>;
};

template<class T>
concept RayQueryable =
    requires(
        const T& index,
        const SpatialRay& ray,
        float maxDistance,
        SpatialLayerMask mask)
{
    {
        index.QueryRay(
            ray,
            maxDistance,
            mask)
    };
};

SpatialOverlapResult QueryAABB(
    const SpatialBackend& backend,
    const SpatialAABB& query,
    SpatialLayerMask mask)
{
    return std::visit(
        [&](const auto& index)
            -> SpatialOverlapResult
        {
            if constexpr (
                requires {
                    index.QueryAABB(
                        query,
                        mask);
                })
            {
                return index.QueryAABB(
                    query,
                    mask);
            }
            else
            {
                throw UnsupportedQuery{};
            }
        },
        backend);
}

